export type ArticleBlock =
  | { type: 'subheading'; text: string }
  | { type: 'paragraph'; text: string }
  | { type: 'list'; items: string[]; ordered?: boolean; start?: number }
  | { type: 'table'; headers: string[]; rows: string[][] }
  | { type: 'code'; text: string }
  | { type: 'image'; src: string; alt: string; caption?: string }
  | { type: 'figure'; id: string; caption?: string }
  | { type: 'quote'; text: string };

export interface ParsedArticle {
  title: string;
  subtitle?: string;
  blocks: ArticleBlock[];
}

/**
 * Parses a lightly-marked-up plain text file into an article:
 *   # Title              -> article title (first line only)
 *   ## Heading           -> first one becomes the subtitle, rest become subheadings
 *   ### Subheading       -> smaller subheading / section marker
 *   > Quote              -> styled blockquote
 *   - list item          -> consecutive lines starting with "- " become a list
 *   | a | b | c |        -> consecutive "| ... |" rows become a table (first row = header)
 *   ```                  -> a fenced block (```...```) becomes a preformatted code block
 *   [[figure:id]]        -> an inline figure (rendered by the article view)
 *   blank line           -> separates blocks
 *   any other line       -> paragraph text (consecutive lines are joined with a space)
 */
export function parseArticle(raw: string): ParsedArticle {
  const lines = raw.replace(/\r\n/g, '\n').split('\n');

  let title = '';
  let subtitle: string | undefined;
  const blocks: ArticleBlock[] = [];

  let paragraphLines: string[] = [];
  let listItems: string[] = [];
  let listOrdered = false;
  let listStart = 1;
  let tableRows: string[][] = [];
  let inCodeBlock = false;
  let codeLines: string[] = [];

  const flushParagraph = () => {
    if (paragraphLines.length > 0) {
      blocks.push({ type: 'paragraph', text: paragraphLines.join(' ').trim() });
      paragraphLines = [];
    }
  };

  const flushList = () => {
    if (listItems.length > 0) {
      blocks.push({
        type: 'list',
        items: listItems,
        ...(listOrdered ? { ordered: true, start: listStart } : {}),
      });
      listItems = [];
      listOrdered = false;
      listStart = 1;
    }
  };

  const flushTable = () => {
    if (tableRows.length > 0) {
      // Filter out markdown separator rows like | :--- | :--- |
      const filtered = tableRows.filter((row) => !row.every((cell) => /^:?-+:?$/.test(cell)));
      if (filtered.length > 0) {
        const [headers, ...rows] = filtered;
        blocks.push({ type: 'table', headers, rows });
      }
      tableRows = [];
    }
  };

  for (const rawLine of lines) {
    const line = rawLine.trim();

    if (line.startsWith('```')) {
      if (inCodeBlock) {
        blocks.push({ type: 'code', text: codeLines.join('\n') });
        codeLines = [];
        inCodeBlock = false;
      } else {
        flushParagraph();
        flushList();
        flushTable();
        inCodeBlock = true;
      }
      continue;
    }

    if (inCodeBlock) {
      codeLines.push(rawLine);
      continue;
    }

    if (line === '') {
      flushParagraph();
      flushList();
      flushTable();
      continue;
    }

    if (line.startsWith('# ')) {
      title = line.slice(2).trim();
      continue;
    }

    if (line.startsWith('## ')) {
      flushParagraph();
      flushList();
      flushTable();
      const text = line.slice(3).trim();
      if (subtitle === undefined && blocks.length === 0) {
        subtitle = text;
      } else {
        blocks.push({ type: 'subheading', text });
      }
      continue;
    }

    if (line.startsWith('### ')) {
      flushParagraph();
      flushList();
      flushTable();
      blocks.push({ type: 'subheading', text: line.slice(4).trim() });
      continue;
    }

    if (line.startsWith('> ')) {
      flushParagraph();
      flushList();
      flushTable();
      blocks.push({ type: 'quote', text: line.slice(2).trim() });
      continue;
    }

    const figureMatch = line.match(/^\[\[figure:([a-z0-9-]+)\]\]$/);
    if (figureMatch) {
      flushParagraph();
      flushList();
      flushTable();
      blocks.push({ type: 'figure', id: figureMatch[1] });
      continue;
    }

    if (line.startsWith(':::figure ') || line.startsWith('[figure:')) {
      flushParagraph();
      flushList();
      flushTable();
      let id = '';
      let caption: string | undefined;
      if (line.startsWith(':::figure ')) {
        const rest = line.slice(10).trim();
        const m = rest.match(/^(\S+)(?:\s+["'](.*?)["'])?/);
        if (m) {
          id = m[1];
          caption = m[2];
        }
      } else {
        const m = line.match(/^\[figure:([^\]\s]+)(?:\s+["'](.*?)["'])?\]/);
        if (m) {
          id = m[1];
          caption = m[2];
        }
      }
      if (id) {
        blocks.push({ type: 'figure', id, caption });
        continue;
      }
    }

    if (line.startsWith('![') && line.includes('](') && line.endsWith(')')) {
      flushParagraph();
      flushList();
      flushTable();
      const match = line.match(/^!\[(.*?)\]\((.*?)\)$/);
      if (match) {
        const alt = match[1];
        let src = match[2].trim();
        let caption: string | undefined;
        const captionMatch = src.match(/^(.*?)\s+["'](.*?)["']$/);
        if (captionMatch) {
          src = captionMatch[1];
          caption = captionMatch[2];
        }
        blocks.push({ type: 'image', src, alt, caption });
        continue;
      }
    }

    if (line.startsWith('|') && line.endsWith('|')) {
      flushParagraph();
      flushList();
      const cells = line
        .slice(1, -1)
        .split('|')
        .map((cell) => cell.trim());
      tableRows.push(cells);
      continue;
    }

    if (line === '---' || line === '***' || line === '___') {
      flushParagraph();
      flushList();
      flushTable();
      continue;
    }

    const numMatch = line.match(/^(\d+)\.\s+/);
    if (line.startsWith('- ') || line.startsWith('* ') || numMatch) {
      flushParagraph();
      flushTable();
      const isNum = !!numMatch;
      if (listItems.length > 0 && isNum !== listOrdered) {
        flushList();
      }
      if (listItems.length === 0) {
        listOrdered = isNum;
        if (isNum && numMatch) {
          listStart = parseInt(numMatch[1], 10);
        }
      }
      const text = isNum
        ? line.replace(/^\d+\.\s+/, '').trim()
        : line.slice(2).trim();
      listItems.push(text);
      continue;
    }

    flushList();
    flushTable();
    paragraphLines.push(line);
  }

  flushParagraph();
  flushList();
  flushTable();

  return { title: title || 'Untitled', subtitle, blocks };
}